{
  "schema_version": "rs-shopping-audit/3",
  "checks": {
    "naturalness": "pass",
    "extraction_fidelity": "fail",
    "fact_boundary": "fail",
    "clarification_policy": "fail"
  },
  "reasons": {
    "naturalness": "顾客以自然口语说明台式机、无线连接问题、偏好和信息尚未确认之处，并提出选购建议请求；这是合理的购物咨询场景。",
    "extraction_fidelity": "提取大体抓住推荐目标及安装、可靠性、速度取舍，但 answer_requirements[1].quote 在原文末尾多了一个分号，属于非逐字引文。此外，“推荐台式机无线连接适配器”的意图基本忠实，但把“电脑是 Windows”提升为严格操作系统条件，与顾客明确说兼容要求尚待确认不符。",
    "fact_boundary": "requirements.r2 将 Windows 记为严格筛选条件，但顾客只陈述电脑是 Windows，并说明具体接口和兼容要求还要确认；应将其作为已知背景，而非已确认的兼容硬条件。recipient 的 self 及画像弱参考推断缺少足够证据：顾客说“家里有台台式机”，没有明确说设备属于本人。目录价格单位未确认，也不能据此补出币种；目录只有有限样本，不代表全站库存或服务状态。",
    "clarification_policy": "可以先给出选购方法，不必因接口和兼容未知而阻止推荐方向；但当前推荐依赖进一步确认时，应将相关动作列入 unresolved_actions，并把接口、具体兼容要求作为 required_for_action 的局部追问，而非仅 optional_refinement。现有 clarification 标为 not_needed 且没有未解决动作，不符合条件。"
  },
  "evidence": [
    {
      "source": "customer",
      "quote": "想添个 USB 网络适配器改善一下。"
    },
    {
      "source": "customer",
      "quote": "比起追求特别高的速度，我更在意安装别太折腾、日常用着可靠；电脑是 Windows，但具体接口和兼容要求我还得确认。"
    },
    {
      "source": "customer",
      "quote": "家里有台台式机"
    },
    {
      "source": "catalog",
      "quote": "USB WiFi Adapter, AX1800 USB 3.0 WiFi 6 Wireless Network Adapter USB Wireless Dongle with Dual Band 2.4GHz/5GHz for Desktop PC Laptop Support Windows 10/11"
    },
    {
      "source": "profile",
      "quote": "past_positive_reviews_not_purchases"
    }
  ],
  "issues": [
    "提取结果 answer_requirements[1].quote 为“比起追求特别高的速度，我更在意安装别太折腾、日常用着可靠；”，末尾分号不在顾客原话中，属于非逐字引用。",
    "requirements.r2 将“电脑是 Windows”设为 strict operating_system 条件；原话仅确认系统背景，并明确表示兼容要求仍需确认。",
    "recipient.target=self 及 profile_policy=weak_reference_if_self 缺少明确的本人归属证据；家庭有台式机不等于确认由本人使用或购买。",
    "接口和兼容信息应可通过先行给出选购方向、再对具体型号作局部确认来处理；clarification.unresolved_actions 为空，且 unknowns 的 blocking_level 仅为 optional_refinement。",
    "不要根据目录价格填写货币单位；price_unit 明示 currency_unconfirmed。"
  ]
}
